function hashText(value){let h=2166136261;for(const c of String(value)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function seededIndex(a,length,salt=0){a.randomStep=(a.randomStep||0)+1;return (((hashText(a.email)+a.randomStep*2654435761+salt)>>>0)%length)}
function destinationFloor(dest){return dest.floor==='roof'?floors.length:Number(dest.floor)}
