function activityChoices(a){const list=[...ACTIVITY_DEFS];if(a.role==='owner')list.push({id:'private-leisure',label:'PRIVATE LEISURE',floor:7,x:2.1,y:1.15,duration:30*60*1000});return list}
function chooseActivity(a){const choices=activityChoices(a).filter(item=>item.id!==a.lastActivity);const choice=choices[seededIndex(a,choices.length,Math.floor(Date.now()/60000))];a.lastActivity=choice.id;return choice}
function beginRoute(a,dest,activity=null){const now=Date.now(),toFloor=destinationFloor(dest),sameFloor=a.floor===toFloor;a.route={phase:sameFloor?'walk-destination':'walk-lift',phaseStarted:now,fromX:Number.isFinite(a.visualX)?a.visualX:a.x,fromY:Number.isFinite(a.visualY)?a.visualY:a.y,fromFloor:a.floor,toFloor,dest,activity};a.motion='walking';a.ambient=`Walking to ${dest.label.toLowerCase()}`;a.activityEndsAt=0}
function phaseDuration(x1,y1,x2,y2){return Math.max(900,Math.hypot(x2-x1,y2-y1)*1050)}
function interpolateRoute(a,targetX,targetY,now){const r=a.route,duration=phaseDuration(r.fromX,r.fromY,targetX,targetY),p=Math.min(1,(now-r.phaseStarted)/duration),ease=p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2;a.visualX=r.fromX+(targetX-r.fromX)*ease;a.visualY=r.fromY+(targetY-r.fromY)*ease;return p>=1}
function finishArrival(a,now){const r=a.route,d=r.dest;a.floor=r.toFloor;a.visualX=d.x;a.visualY=d.y;a.inElevator=false;if(r.activity){a.ambient=r.activity.label;a.motion='activity';a.activityEndsAt=now+r.activity.duration;a.route=null;activity(a,`arrived at ${r.activity.label.toLowerCase()}`)}else{a.ambient='';a.motion=a.presence==='online'?'typing':'standing';a.route=null;a.activityEndsAt=a.presence==='offline'?now+5000:0}}
function updateAgentMotion(a,now){
 if(a.manual){const dt=Math.min(.05,(now-(a.manualAt||now))/1000);a.manualAt=now;let remaining=dt*.46;while(a.manualPath?.length&&remaining>0){const target=a.manualPath[0],dx=target.x-a.visualX,dy=target.y-a.visualY,d=Math.hypot(dx,dy);if(d<=remaining){a.visualX=target.x;a.visualY=target.y;remaining-=d;a.manualPath.shift()}else{a.visualX+=dx/d*remaining;a.visualY+=dy/d*remaining;remaining=0}}a.manualState=a.manualPath?.length?'walk':a.manualAfter||'idle';a.motion=a.manualState==='walk'?'walking':a.manualState==='work'?'typing':'standing';return}
 if(!a.route){if(a.presence==='offline'&&(!a.activityEndsAt||now>=a.activityEndsAt)){const next=chooseActivity(a);beginRoute(a,next,next)}return}
 const r=a.route;
 if(r.phase==='walk-lift'&&interpolateRoute(a,LIFT_POINT.x,LIFT_POINT.y,now)){a.visualX=LIFT_POINT.x;a.visualY=LIFT_POINT.y;a.motion='standing';r.phase='wait-lift';if(!elevator.moving&&!elevator.passenger){elevator.position=a.floor;elevator.floor=a.floor;elevator.target=r.toFloor;elevator.passenger=a.id;elevator.moving=true;a.inElevator=true;r.phase='elevator';updateElevatorUI()}}
 else if(r.phase==='wait-lift'&&!elevator.moving&&!elevator.passenger){elevator.position=a.floor;elevator.floor=a.floor;elevator.target=r.toFloor;elevator.passenger=a.id;elevator.moving=true;a.inElevator=true;r.phase='elevator';updateElevatorUI()}
 else if(r.phase==='walk-destination'&&interpolateRoute(a,r.dest.x,r.dest.y,now))finishArrival(a,now)
}
function ambientProp(a){if(a.motion!=='activity')return;const pulse=Date.now()/240;if(a.lastActivity==='smoking'){ctx.strokeStyle='#f4f7fa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(13,29);ctx.lineTo(21,26);ctx.stroke()}else if(a.lastActivity==='gaming'){ctx.fillStyle='#d7e2ef';ctx.beginPath();ctx.roundRect(-10,24,20,8,4);ctx.fill()}else if(a.lastActivity==='basketball'){const phase=(pulse%4),bx=phase<2?14+phase*9:50-(phase-2)*18,by=phase<2?18-Math.sin(phase*Math.PI/2)*27:18+Math.sin((phase-2)*Math.PI/2)*15;ctx.fillStyle='#f58b3a';ctx.strokeStyle='#5e2d13';ctx.lineWidth=1;ctx.beginPath();ctx.arc(bx,by,5,0,Math.PI*2);ctx.fill();ctx.stroke()}else if(a.lastActivity==='canteen'){ctx.fillStyle='#f1d08b';ctx.beginPath();ctx.arc(15,25+Math.sin(pulse)*3,4,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c5d5dd';ctx.beginPath();ctx.moveTo(10,23);ctx.lineTo(18,29);ctx.stroke()}else if(a.lastActivity==='gym'){ctx.strokeStyle='#dce9ef';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-18,18+Math.sin(pulse)*6);ctx.lineTo(18,18-Math.sin(pulse)*6);ctx.stroke();[-20,20].forEach(x=>{ctx.beginPath();ctx.arc(x,18,5,0,Math.PI*2);ctx.stroke()})}else if(a.lastActivity==='toilet'){ctx.fillStyle='#8ee7ff';ctx.fillRect(-14,31,28,3)}ctx.fillStyle='#07101ddf';ctx.strokeStyle='#526a82';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(-38,44,76,12,5);ctx.fill();ctx.stroke();ctx.fillStyle='#eaf3f8';ctx.font='800 6px system-ui';ctx.textAlign='center';ctx.fillText(a.ambient||'',0,52)}
function drawAgent(a){if(activeFloor==='all')return;queueAvatar(a,a.inElevator?3.55:a.visualX,a.inElevator?-2.08:a.visualY,a.floor===floors.length?towerTop()+.12:floorZ(a.inElevator?elevator.position:a.floor)+.17)}
const drawAgentWorld=drawAgent;
function render(){if(document.hidden||!hqVisible){requestAnimationFrame(render);return}$('avatarActions').hidden=Boolean(prototype)||!myAgent();const now=Date.now();agents.forEach(a=>updateAgentMotion(a,now));animateElevator();ctx.clearRect(0,0,W,H);monitorHitboxes=[];officeGeometry=[];renderActors=[];labelQueue=[];labelReservations=[];agents.forEach(a=>a.screen=null);drawGround();if(activeFloor==='all'){drawTowerExterior();agents.filter(a=>!a.inElevator).forEach(drawAgentWorld)}else if(activeFloor==='roof'){drawRoof();agents.filter(a=>!a.inElevator&&a.floor===floors.length).forEach(drawAgentWorld)}else{const f=floors[Number(activeFloor)];if(f){drawShell(f);if(f.id===5)agents.filter(a=>!a.inElevator&&a.floor===5).forEach(a=>drawOfficeAvatar(a,floorZ(5)+.17,false));else if(f.id===7&&session.canAccessOwnerRoom)agents.filter(a=>a.role==='owner'&&!a.inElevator&&a.floor===7).forEach(a=>drawOfficeAvatar(a,floorZ(7)+.17,true));else agents.filter(a=>!a.inElevator&&a.floor===f.id).forEach(drawAgentWorld)}}agents.filter(a=>a.inElevator).forEach(drawAgentWorld);if(prototype){try{prototype.frame({W,H,camera,scale:worldScale(),floor:activeFloor,z:floorZ(5)+.17,geometry:officeGeometry,desks:officeDeskPositions,now})}catch(error){prototype.dispose();prototype=null;toast('3D prototype stopped safely. Building remains available.');console.error(error)}}if(renderActors.length&&!workforce&&!workforceLoading&&!renderFault)ensureWorkforce();if(workforce){try{workforce.frame({W,H,camera,scale:worldScale(),floor:activeFloor,geometry:officeGeometry,now,actors:renderActors,demo:Boolean(prototype)})}catch(error){workforce.dispose();workforce=null;renderFault=true;toast('3D unavailable. Workforce data remains available.');console.error(error)}}paintLabels();if(Date.now()-monitorOverlayAt>120){monitorOverlayAt=Date.now();updateMonitorTargets()}if(keybotPulse>0)keybotPulse-=.3;requestAnimationFrame(render)}

function renderFloorSelector(){const expand=session.canConfigure?`<button class="floor-button overview" data-floor="expand"><b>＋</b><span>Expand</span><i>Saved company floor</i></button>`:'';$('floorSelector').innerHTML=`<span>FLOORS</span>${[...floors].reverse().map(f=>`<button class="floor-button ${f.id===7&&!session.canAccessOwnerRoom?'locked':''}" data-floor="${f.id}"><b>${f.number}</b><span>${f.name}</span><i>${f.id===7&&!session.canAccessOwnerRoom?'Owner access only':f.sub}</i></button>`).join('')}<button class="floor-button" data-floor="roof"><b>R</b><span>Rooftop</span><i>50% court · 50% social deck</i></button><button class="floor-button overview active" data-floor="all"><b>∞</b><span>Full tower</span><i>${floors.length} floors</i></button>${expand}`;$('floorSelector').querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>b.dataset.floor==='expand'?expandTower():selectFloor(b.dataset.floor))}
function floorPayload(){return floors.slice(baseFloors.length).map(f=>({name:f.name,sub:f.sub}))}
function expandTower(){if(!session.canConfigure){toast('Only an Owner or Admin can configure floors.');return}if(floors.length>=MAX_FLOORS){toast(`Expansion limit is ${MAX_FLOORS} floors.`);return}const answer=window.prompt('Name the new KeyHQ floor or department:',`Expansion ${floors.length-baseFloors.length+1}`);if(answer===null)return;const name=String(answer||'Future Workspace').trim().slice(0,32)||'Future Workspace',id=floors.length;floors.push({id,number:String(id+1).padStart(2,'0'),name,sub:'Configured company workspace',color:'#263747',accent:'#75e6ff'});renderFloorSelector();selectFloor(id);window.parent!==window&&window.parent.postMessage({type:'KEYHQ_SAVE_CONFIG',floors:floorPayload()},location.origin);toast(`Saving floor ${id+1}…`)}
function centerSelectedView(animated=true){const value=activeFloor,target=value==='all'?{x:20,y:18,z:towerTop()*.47,zoom:.7}:value==='roof'?{x:48,y:82,z:towerTop()+.42,zoom:1.06}:{x:62,y:108,z:floorZ(Number(value))+.72,zoom:Number(value)===5?1.4:Number(value)===4?1.22:1.3};if(value!=='all'){target.x=innerWidth<=760?0:40;target.y=innerWidth<=640?10:50;target.zoom=Math.min(target.zoom,innerWidth<=640?1.12:1.2)}if(animated)moveCamera(target);else Object.assign(camera,target)}
function selectFloor(value){if(Number(value)===7&&!session.canAccessOwnerRoom){toast('Level 8 is private to enabled Owner accounts.');return}activeFloor=value==='all'||value==='roof'?value:Number(value);document.querySelectorAll('.floor-button').forEach(b=>b.classList.toggle('active',String(b.dataset.floor)===String(value)));$('projector').classList.toggle('visible',Number(activeFloor)===4);$('locationTracker').hidden=!(Number(activeFloor)===5&&session.role==='owner');if(value==='all')$('floorSummary').textContent=`KeyHQ V0.7 · ${floors.length} connected levels plus destination rooftop.`;else if(value==='roof')$('floorSummary').textContent='Destination rooftop · basketball court and shared social deck';else{const f=floors[Number(value)];$('floorSummary').textContent=`KeyHQ · Level ${f.id+1} ${f.name} — ${f.sub}`}centerSelectedView(true);const me=agents.find(a=>a.email===String(session.email||'').toLowerCase()&&a.presence==='online');if(me&&!me.manual&&Number(value)===7&&me.role==='owner'&&me.floor!==7&&!me.route)beginRoute(me,{id:'owner-work',label:'OWNER ROOM',floor:7,x:1.5,y:-.37,duration:0});else if(me&&!me.manual&&Number(value)===5&&me.floor===7&&!me.route)beginRoute(me,deskDestination(me))}
function moveCamera(target){const start={...camera};let frame=0;function step(){frame++;const t=Math.min(frame/24,1),e=1-Math.pow(1-t,3);Object.keys(target).forEach(k=>camera[k]=start[k]+(target[k]-start[k])*e);if(t<1)requestAnimationFrame(step)}step()}
function pick(mx,my){let best=null,dist=28;agents.forEach(a=>{if(!a.screen)return;const d=Math.hypot(mx-a.screen.x,my-a.screen.y);if(d<dist){best=a;dist=d}});return best}
