function html(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function moneyValue(value,currency='MYR'){try{return new Intl.NumberFormat('en-MY',{style:'currency',currency:currency||'MYR'}).format(Number(value)||0)}catch(_){return `${currency||'MYR'} ${(Number(value)||0).toFixed(2)}`}}
