 const person=hit?.person||null,rows=quotationsFor(person),dialog=$('quotationDialog');selectedQuoteId='';
 $('quotationEmployee').textContent=person?`${person.name} · Desk ${String(hit.deskNo).padStart(2,'0')}`:`Desk ${String(hit?.deskNo||'').padStart(2,'0')} · Unassigned`;
