 $('quotationList').innerHTML=rows.length?rows.map(q=>{const sealed=String(q.status).toLowerCase()==='sealed';return `<button class="quotation-record" data-quote-id="${html(q.id)}" ${sealed?'':'disabled'}><strong>${html(q.reference)}</strong><span class="amount">${html(moneyValue(q.amount,q.currency))}</span><small>${html(q.customer||'Customer not recorded')} · ${html(q.project||'No project')}</small><span class="status">${html(q.date||'No date')} · ${html(q.status)}</span><span class="pdf-kind">${sealed?'OPEN ORIGINAL KEYSUITE PDF':'PDF AVAILABLE AFTER SEALING'}</span></button>`}).join(''):`<div class="quotation-empty">${html(session.quotationError||'No authorized quotation records were returned for this employee. No demo records are shown.')}</div>`;
