function renderPeopleEditor(){$('peopleEditor').innerHTML=agents.map(a=>`<div class="person-edit-row" data-email="${html(a.email)}"><div><strong>${html(a.name)}${a.kind==='ai'?' · AI':''}</strong><small>${html(a.role)} · ${html(a.email)} · ${html(a.accountState)}</small></div><label>Desk<select data-field="deskNo">${officeDeskPositions.map(d=>`<option value="${d.no}" ${d.no===a.deskNo?'selected':''}>${String(d.no).padStart(2,'0')}</option>`).join('')}</select></label><label>Avatar<select data-field="gender"><option value="female" ${a.gender==='female'?'selected':''}>Female</option><option value="male" ${a.gender==='male'?'selected':''}>Male</option><option value="nonbinary" ${a.gender==='nonbinary'?'selected':''}>Nonbinary</option></select></label><label>Accent<input data-field="accent" type="color" value="${html(a.color)}"></label></div>`).join('')}
