function myCommand(action,target){const a=myAgent();if(!a){toast('Your authenticated avatar is unavailable.');return}if(a.inElevator){toast('Wait until the elevator arrives.');return}if(action==='auto'){a.manual=false;a.manualPath=[];a.manualState=null;manualMove=false;beginRoute(a,deskDestination(a));$('avatarActionState').textContent='Automatic behaviour resumed';return}if(action==='move'){if(a.floor!==5||Number(activeFloor)!==5){toast('Select Level 6 while your avatar is in the office to move.');return}manualMove=true;action='idle';$('avatarActionState').textContent='Click a clear office floor area.'}else manualMove=false;
 const seat=avatarDesk(a);if((action==='sit'||action==='work')&&a.floor!==5){toast('Return to Level 6 using Auto before sitting at your desk.');return}if(action==='sit'||action==='work')target={x:seat.x,y:seat.y-seat.facing*.43};const path=target?workforce?.pathTo({x:a.visualX,y:a.visualY},target,officeDeskPositions):[];if(target&&!path){toast('No clear route to that location.');return}a.manual=true;a.route=null;a.manualPath=path||[];a.manualAfter=action;a.manualState=path?.length?'walk':action;a.manualAt=Date.now();if(!manualMove)$('avatarActionState').textContent='Manual control · choose Auto to resume';}

