function renderLocationTracker(){$('locationList').innerHTML=agents.map(a=>`<button class="location-row" data-location-id="${html(a.id)}"><strong>${html(a.name)}${a.kind==='ai'?' · AI':''}</strong><span>${html(remainingText(a))}</span><small>${html(locationOf(a))}</small></button>`).join('');$('locationList').querySelectorAll('[data-location-id]').forEach(row=>row.onclick=()=>jumpToAgent(row.dataset.locationId))}
