function displayTime(value){if(!value)return 'Last checked '+(session.refreshedAt?new Date(session.refreshedAt).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'—');const date=new Date(value);return Number.isNaN(date.getTime())?'Updated —':`Updated ${date.toLocaleString()}`}
function jumpToAgent(id){if(session.role!=='owner')return;const a=agents.find(item=>item.id===id);if(!a)return;selected=id;const target=a.inElevator?Math.round(elevator.position):a.floor;if(target===floors.length)selectFloor('roof');else selectFloor(Math.min(target,floors.length-1));showAgent(id,false);moveCamera({x:62-a.visualX*16,y:108+a.visualY*9,z:target===floors.length?towerTop()+.42:floorZ(target)+.72,zoom:1.5})}
