function animateElevator(){if(!elevator.moving)return;const delta=elevator.target-elevator.position;elevator.position+=delta*.035;if(Math.abs(delta)<.012){elevator.position=elevator.target;elevator.floor=elevator.target;elevator.moving=false;const a=agents.find(x=>x.id===elevator.passenger);if(a?.route){a.floor=elevator.target;a.inElevator=false;a.visualX=LIFT_POINT.x;a.visualY=LIFT_POINT.y;a.route.phase='walk-destination';a.route.phaseStarted=Date.now();a.route.fromX=LIFT_POINT.x;a.route.fromY=LIFT_POINT.y;a.motion='walking'}elevator.passenger=null;updateElevatorUI();renderTeam()}}
