function klParts(){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kuala_Lumpur',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());return {hour:Number(parts.find(p=>p.type==='hour')?.value||0),text:`${parts.find(p=>p.type==='hour')?.value||'00'}:${parts.find(p=>p.type==='minute')?.value||'00'} MYT`}}
